"""Decode String — stack of (prefix, repeat count).

'[' saves the text built so far along with the multiplier; ']' pops it and
appends the repeated chunk.

Time: O(length of the decoded string)   Space: O(depth)
"""


class Solution:
    def decodeString(self, s: str) -> str:
        stack, current, count = [], "", 0
        for ch in s:
            if ch.isdigit():
                count = count * 10 + int(ch)
            elif ch == "[":
                stack.append((current, count))
                current, count = "", 0
            elif ch == "]":
                prefix, repeat = stack.pop()
                current = prefix + current * repeat
            else:
                current += ch
        return current
